package com.google.javascript.jscomp.type;

import com.google.common.base.Preconditions;
import com.google.javascript.jscomp.CodingConvention;
import com.google.javascript.jscomp.Compiler;
import com.google.javascript.jscomp.jasmine.TestUtils;
import com.google.javascript.jscomp.javascript.AST_GETPROP;
import com.google.javascript.jscomp.javascript.AST_NAME;
import com.google.javascript.jscomp.javascript.FlowScope;
import com.google.javascript.jscomp.javascript.JSType;
import com.google.javascript.jscomp.javascript.JSTypeRegistry;
import com.google.javascript.jscomp.javascript.Node;
import com.google.javascript.jscomp.javascript.Scanner;
import com.google.javascript.jscomp.javascript.StaticSlot;
import com.google.javascript.jscomp.javascript.Token;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import com.google.javascript.rhino.jstype.EnumElementType;
import com.google.javascript.rhino.jstype.FunctionType;
import com.google.javascript.rhino.jstype.JSType;
import com.google.javascript.rhino.jstype.JSTypeNative;
import com.google.javascript.rhino.jstype.JSTypeRegistry;
import com.google.javascript.rhino.jstype.ObjectType;
import com.google.javascript.rhino.jstype.ParameterizedType;
import com.google.javascript.rhino.jstype.StaticSlot;
import com.google.javascript.rhino.jstype.TemplateType;
import com.google.javascript.rhino.jstype.UnionType;
import com.google.javascript.rhino.jstype.Visitor;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static com.google.javascript.jscomp.Assert.assertTrue;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ChainableReverseAbstractInterpreter_getTypeIfRefinable_TriageGen2Test {

    private JSTypeRegistry typeRegistry;
    private CodingConvention convention;
    private TestableInterpreter interpreter;
    private JSType stringType;
    private JSType unknownType;

    // Subclass to expose the protected method for testing
    private static class TestableInterpreter extends ChainableReverseAbstractInterpreter {
        protected TestableInterpreter(CodingConvention convention, JSTypeRegistry typeRegistry) {
            super(convention, typeRegistry);
        }

        @Override
        public JSType getTypeIfRefinable(Node node, FlowScope scope) {
            return super.getTypeIfRefinable(node, scope);
        }

        // Mocking getNativeType which is likely internal/protected
        @Override
        protected JSType getNativeType(JSType type) {
            return type;
        }
    }

    @Before
    public void setUp() {
        typeRegistry = JSTypeRegistry.getNew();
        convention = TestUtils.createCodingConvention();
        interpreter = new TestableInterpreter(convention, typeRegistry);
        stringType = typeRegistry.getNativeType("string");
        unknownType = typeRegistry.getNativeType("unknown");
    }

    @Test
    public void testTokenName_SlotExists_WithType() {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(Token.NAME);
        when(node.getString()).thenReturn("x");

        FlowScope scope = mock(FlowScope.class);
        StaticSlot<JSType> slot = mock(StaticSlot.class);
        when(scope.getSlot("x")).thenReturn(slot);
        when(slot.getType()).thenReturn(stringType);

        JSType result = interpreter.getTypeIfRefinable(node, scope);
        assertEquals(stringType, result);
    }

    @Test
    public void testTokenName_SlotExists_WithoutType_FallbackToNodeType() {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(Token.NAME);
        when(node.getString()).thenReturn("x");
        when(node.getJSType()).thenReturn(stringType);

        FlowScope scope = mock(FlowScope.class);
        StaticSlot<JSType> slot = mock(StaticSlot.class);
        when(scope.getSlot("x")).thenReturn(slot);
        when(slot.getType()).thenReturn(null);

        JSType result = interpreter.getTypeIfRefinable(node, scope);
        assertEquals(stringType, result);
    }

    @Test
    public void testTokenName_SlotDoesNotExist() {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(Token.NAME);
        when(node.getString()).thenReturn("y");

        FlowScope scope = mock(FlowScope.class);
        when(scope.getSlot("y")).thenReturn(null);

        JSType result = interpreter.getTypeIfRefinable(node, scope);
        assertNull(result);
    }

    @Test
    public void testTokenGetProp_QualifiedNameIsNull() {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(Token.GETPROP);
        when(node.getQualifiedName()).thenReturn(null);

        FlowScope scope = mock(FlowScope.class);
        JSType result = interpreter.getTypeIfRefinable(node, scope);
        assertNull(result);
    }

    @Test
    public void testTokenGetProp_SlotExists_WithType() {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(Token.GETPROP);
        when(node.getQualifiedName()).thenReturn("obj.prop");

        FlowScope scope = mock(FlowScope.class);
        StaticSlot<JSType> slot = mock(StaticSlot.class);
        when(scope.getSlot("obj.prop")).thenReturn(slot);
        when(slot.getType()).thenReturn(stringType);

        JSType result = interpreter.getTypeIfRefinable(node, scope);
        assertEquals(stringType, result);
    }

    @Test
    public void testTokenGetProp_SlotExists_WithoutType_FallbackToNodeType() {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(Token.GETPROP);
        when(node.getQualifiedName()).thenReturn("obj.prop");
        when(node.getJSType()).thenReturn(stringType);

        FlowScope scope = mock(FlowScope.class);
        StaticSlot<JSType> slot = mock(StaticSlot.class);
        when(scope.getSlot("obj.prop")).thenReturn(slot);
        when(slot.getType()).thenReturn(null);

        JSType result = interpreter.getTypeIfRefinable(node, scope);
        assertEquals(stringType, result);
    }

    @Test
    public void testTokenGetProp_SlotDoesNotExist_FallbackToNodeType() {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(Token.GETPROP);
        when(node.getQualifiedName()).thenReturn("obj.prop");
        when(node.getJSType()).thenReturn(stringType);

        FlowScope scope = mock(FlowScope.class);
        when(scope.getSlot("obj.prop")).thenReturn(null);

        JSType result = interpreter.getTypeIfRefinable(node, scope);
        assertEquals(stringType, result);
    }

    @Test
    public void testTokenGetProp_AllNull_FallbackToUnknown() {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(Token.GETPROP);
        when(node.getQualifiedName()).thenReturn("obj.prop");
        when(node.getJSType()).thenReturn(null);

        FlowScope scope = mock(FlowScope.class);
        when(scope.getSlot("obj.prop")).thenReturn(null);

        // The code uses getNativeType(UNKNOWN_TYPE). 
        // Since we mocked getNativeType to return the input, we assume UNKNOWN_TYPE is passed.
        JSType result = interpreter.getTypeIfRefinable(node, scope);
        // In our mock, getNativeType(UNKNOWN_TYPE) returns UNKNOWN_TYPE
        assertNotNull(result);
    }

    @Test
    public void testOtherTokenTypes() {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(Token.ASSIGN);
        FlowScope scope = mock(FlowScope.class);

        JSType result = interpreter.getTypeIfRefinable(node, scope);
        assertNull(result);
    }
}
